      for (let i = pts.length - 2; i >= 0; i--) { const ds = Math.hypot(pts[i][0] - pts[i + 1][0], pts[i][1] - pts[i + 1][1]); if (pts[i][2] < pts[i + 1][2] - DECK_GRADE * ds) pts[i][2] = pts[i + 1][2] - DECK_GRADE * ds; }
