      const th=STREET_TEXT_HEIGHT[L2[i+4]],hw=th*r[2]/FS/2,hh=th*RH/FS/2;
      const mesh=streetLabelGeometry(f,hw,hh,(x,z)=>roadHeight(x,z)+0.38);
