    groupCity.add(indegoSolid);
    groupCity.add(indegoBike);
    groupCity.add(indegoBadge);
    indegoReady = true;
    syncIndegoBtn();
    setInterval(() => indegoPoll(false), INDEGO_POLL);
    document.addEventListener('visibilitychange', () => { if (!document.hidden) indegoPoll(false); });
