    box(0.42, 0.04, 0.04, -0.3, 0.035, 0, 0.8, 0.8, 0.83);         // tail boom
    box(0.055, 0.15, 0.012, -0.485, 0.08, 0, 0.72, 0.2, 0.18);     // tail fin, warning red
    box(0.012, 0.12, 0.018, -0.5, 0.1, 0.028, 0.25, 0.25, 0.28);   // tail rotor
