      box(0.34, 0.013, 0.016, 0.06, -0.12, sz, 0.35, 0.36, 0.4);   // skids
      box(0.012, 0.06, 0.014, -0.04, -0.09, sz, 0.35, 0.36, 0.4);  // struts
      box(0.012, 0.06, 0.014, 0.17, -0.09, sz, 0.35, 0.36, 0.4);
