    if (s.name) v.name = String(s.name).trim() || v.name;
    if (s.type > 0) { v.tc = s.type; v.tn = SHIP_TYPE(s.type); }
    if (s.len > 4) v.len = clamp(s.len, 8, 340);
    if (s.beam > 1) v.beam = clamp(s.beam, 3, 52);
