      const rec = { id: String(r.id || ''), o: clamp(r.o | 0, 1, 3), addr: String(r.addr || ''), permits: Array.isArray(r.permits) ? r.permits.slice(0, 4) : [], mx: ln.mx, mz: ln.mz, my: closureY(ln.mx, ln.mz) };
